head.script:

scwin.onpageload = function () {
	imports("uiplugin.popup");
};

scwin.trigger1_onclick = function (e) {
//wframe popup
	var options = {
		id: "popup7",
		name: "popup7",
		type: "wframePopup",
		width: "600px",
		height: "600px",
		popupUrl : "wFrame_floatingLayer_WESD-1741_(WSQ-5825)_src.xml",
		modal : "",
		windowMoveType : "restrict"

	};

	$p.openPopup("", options);

};
